-- Read-only verification immediately after import.
select 'products' as table_name,count(*) as actual_count,38 as expected_count from public.kmed_products union all select 'movements',count(*),2 from public.kmed_movements;
-- Every expected product quantity and deletion state should match.
WITH expected(id,quantity,deleted) AS (VALUES ('item-001',5,0),('item-002',6,0),('item-003',4,0),('item-004',3,0),('item-005',6,0),('item-006',23,0),('item-007',22,0),('item-008',7,0),('item-009',17,0),('item-010',15,0),('item-011',0,0),('item-012',3,0),('item-013',1,0),('item-014',2.5,0),('item-015',0,0),('item-016',315,0),('item-017',93,0),('item-018',250,0),('item-019',109,0),('item-020',273,0),('item-021',269,0),('item-022',1,0),('item-023',349,0),('item-024',108,0),('item-025',0,0),('item-026',3,0),('item-027',8,0),('item-028',0,0),('item-029',0,0),('item-030',3,0),('item-031',1,0),('item-032',0,0),('item-033',12,0),('item-034',3,0),('item-035',4,0),('item-036',0,0),('item-037',1,0),('item-038',0,0)),actual AS (SELECT p.id,round(p.opening+coalesce(sum(m.delta),0),4) quantity,p.deleted FROM public.kmed_products p LEFT JOIN public.kmed_movements m ON m.product_id=p.id GROUP BY p.id) SELECT e.id,e.quantity expected_quantity,a.quantity actual_quantity,e.deleted expected_deleted,a.deleted actual_deleted FROM expected e FULL JOIN actual a ON a.id=e.id WHERE e.id IS NULL OR a.id IS NULL OR e.quantity IS DISTINCT FROM a.quantity OR e.deleted IS DISTINCT FROM a.deleted;
